const upsertBackupSettings = `-- name: UpsertBackupSettings :one
INSERT INTO backup_settings (id, repository, credentials, password, keep_daily, keep_weekly, keep_monthly, hour, updated_at, updated_by, storage_id, storage_path)
VALUES (1, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
ON CONFLICT (id) DO UPDATE SET
    repository = excluded.repository, credentials = excluded.credentials, password = excluded.password,
    keep_daily = excluded.keep_daily, keep_weekly = excluded.keep_weekly, keep_monthly = excluded.keep_monthly,
    hour = excluded.hour, updated_at = excluded.updated_at, updated_by = excluded.updated_by,
    storage_id = excluded.storage_id, storage_path = excluded.storage_path
RETURNING id, repository, credentials, password, keep_daily, keep_weekly, keep_monthly, hour, updated_at, updated_by, storage_id, storage_path, verify
`

type UpsertBackupSettingsParams struct {
	Repository  string
	Credentials []byte
	Password    []byte
	KeepDaily   int64
	KeepWeekly  int64
	KeepMonthly int64
	Hour        int64
	UpdatedAt   time.Time
	UpdatedBy   string
	StorageID   *int64
	StoragePath string
}

func (q *Queries) UpsertBackupSettings(ctx context.Context, arg UpsertBackupSettingsParams) (BackupSetting, error) {
	row := q.db.QueryRowContext(ctx, upsertBackupSettings,
		arg.Repository,
		arg.Credentials,
		arg.Password,
		arg.KeepDaily,
		arg.KeepWeekly,
		arg.KeepMonthly,
		arg.Hour,
		arg.UpdatedAt,
		arg.UpdatedBy,
		arg.StorageID,
		arg.StoragePath,
	)
	var i BackupSetting
	err := row.Scan(
		&i.ID,
		&i.Repository,
		&i.Credentials,
		&i.Password,
		&i.KeepDaily,
		&i.KeepWeekly,
		&i.KeepMonthly,
		&i.Hour,
		&i.UpdatedAt,
		&i.UpdatedBy,
		&i.StorageID,
		&i.StoragePath,
		&i.Verify,
	)
	return i, err
}
